package version

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"golang.org/x/mod/modfile"
	"golang.org/x/mod/semver"
)

// Every place that spells the paired runtime version agrees with the factory's: the factory's own go.mod (it builds
// against runtime/ through a replace, but the require line is what `factory init` copies into new projects), and every
// project under examples/ (generated by this factory, so they import the paired runtime).
func TestRuntimeVersionPaired(t *testing.T) {
	if !semver.IsValid(Factory) || semver.Canonical(Factory) != Factory {
		t.Fatalf("Factory %q is not a canonical semantic version", Factory)
	}
	root := filepath.Join("..", "..")
	mods := []string{filepath.Join(root, "go.mod")}
	ex, _ := filepath.Glob(filepath.Join(root, "examples", "*", "*", "go.mod"))
	ex2, _ := filepath.Glob(filepath.Join(root, "examples", "*", "*", "*", "go.mod"))
	mods = append(append(mods, ex...), ex2...)
	if len(mods) < 2 {
		t.Fatalf("no example projects found: %v", mods)
	}
	for _, m := range mods {
		b, err := os.ReadFile(m)
		if err != nil {
			t.Fatal(err)
		}
		f, err := modfile.ParseLax(m, b, nil)
		if err != nil {
			t.Fatal(err)
		}
		found := false
		for _, r := range f.Require {
			switch r.Mod.Path {
			case RuntimeModule:
				found = true
				if r.Mod.Version != Runtime {
					t.Errorf("%s: %s %s, the factory is %s (scripts/release.sh bump)", m, RuntimeModule, r.Mod.Version, Factory)
				}
			case OldRuntimeModule:
				t.Errorf("%s: still requires %s (factory upgrade)", m, OldRuntimeModule)
			}
		}
		if !found && !strings.Contains(string(b), "// no runtime") {
			t.Errorf("%s: does not require %s", m, RuntimeModule)
		}
	}
}

// The runtime knows its own version (factory-runtime version, the server's start-up log): the same number.
func TestRuntimeModuleVersion(t *testing.T) {
	b, err := os.ReadFile(filepath.Join("..", "..", "runtime", "version", "version.go"))
	if err != nil {
		t.Fatal(err)
	}
	m := regexp.MustCompile(`const Version = "([^"]+)"`).FindSubmatch(b)
	if m == nil || string(m[1]) != Runtime {
		t.Fatalf("runtime/version/version.go: Version %q, want %q", m, Runtime)
	}
}
